SELECT CASE WHEN p.stock_qty >= 308 THEN 'high' WHEN p.stock_qty >= 197 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, p.supplier_id, MAX(oi.quantity) - MIN(oi.quantity) AS quantity_range, COUNT(DISTINCT oi.quantity) AS unique_products FROM order_items oi INNER JOIN products p ON p.id = oi.product_id RIGHT JOIN orders o ON oi.order_id = o.id GROUP BY CASE WHEN p.stock_qty >= 308 THEN 'high' WHEN p.stock_qty >= 197 THEN 'mid' ELSE 'low' END, p.supplier_id ORDER BY p.supplier_id
